package cn.minidayz.patcher;
import java.io.*;import java.util.*;import java.util.zip.*;import java.security.*;import java.security.cert.*;import org.json.*;import dalvik.system.DexClassLoader;
/** Only code signed by the pinned P identity can be loaded into the app process. */
public final class ExternalEngine {
 public static JSONObject signed(File file,String kind,byte[] cert)throws Exception{ZipFile z=new ZipFile(file);try{FilesEx.entries(z);ZipEntry json=z.getEntry(kind+".json"),sig=z.getEntry(kind+".sig");FilesEx.require(json!=null&&sig!=null,"E_PACKAGE_FORMAT: 缺少 "+kind+" 签名清单");byte[] raw=FilesEx.read(z.getInputStream(json),16777216);Signature v=Signature.getInstance("SHA256withRSA");v.initVerify((X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(cert)));v.update(raw);FilesEx.require(v.verify(FilesEx.read(z.getInputStream(sig),16384)),"E_PACKAGE_SIGNATURE: 签名无效");JSONObject m=new JSONObject(new String(raw,"UTF-8"));FilesEx.require(Signing.CERT_SHA.equals(m.getString("signer_sha256")),"E_PACKAGE_SIGNER");return m;}finally{z.close();}}
 public static JSONObject verify(File file,byte[] cert)throws Exception{JSONObject m=signed(file,"engine",cert);FilesEx.require(m.getString("format").equals("mdz-engine/1")&&m.getInt("api")==1&&m.getString("entry_class").equals("mdz.engine.UnityEngine"),"E_ENGINE_API");JSONObject files=m.getJSONObject("files");FilesEx.require(files.length()==2&&files.has("classes.dex")&&files.has("locators.json"),"E_ENGINE_FILES");ZipFile z=new ZipFile(file);try{Iterator<String> names=files.keys();while(names.hasNext()){String n=names.next();JSONObject record=files.getJSONObject(n);ZipEntry e=z.getEntry(n);FilesEx.require(e!=null&&e.getSize()==record.getLong("size")&&e.getSize()<=16777216,"E_ENGINE_FILE_SIZE");FilesEx.require(FilesEx.hex(FilesEx.digest(z.getInputStream(e),FilesEx.QUIET)).equals(record.getString("sha256")),"E_ENGINE_FILE_HASH");}}finally{z.close();}return m;}
 public static void apply(final File engine,byte[] cert,String id,final File before,final File after,File work,JSONArray rules,final FilesEx.Watch watch)throws Exception{JSONObject m=verify(engine,cert);FilesEx.require(id.equals(m.getString("id")),"E_ENGINE_ID: 请导入匹配的引擎包");FilesEx.require(work.mkdirs()||work.isDirectory(),"E_ENGINE_WORK");ZipFile z=new ZipFile(engine);File dex=new File(work,"engine.dex");String map;try{byte[] bytes=FilesEx.read(z.getInputStream(z.getEntry("classes.dex")),16777216);FileOutputStream out=new FileOutputStream(dex);try{FilesEx.require(dex.setReadOnly(),"E_ENGINE_READONLY");out.write(bytes);out.getFD().sync();}finally{out.close();}map=new String(FilesEx.read(z.getInputStream(z.getEntry("locators.json")),4194304),"UTF-8");}finally{z.close();}FilesEx.require(before.length()>0&&FilesEx.sha(before,watch).equals(new JSONObject(map).getString("input_sha256")),"E_ENGINE_BASE: 数据文件不属于此引擎支持的版本");DexClassLoader loader=new DexClassLoader(dex.getPath(),work.getPath(),null,ExternalEngine.class.getClassLoader());final Thread worker=Thread.currentThread();final java.util.concurrent.atomic.AtomicBoolean finished=new java.util.concurrent.atomic.AtomicBoolean(false);Thread monitor=new Thread(new Runnable(){public void run(){while(!finished.get()){if(watch.cancelled()){worker.interrupt();return;}try{Thread.sleep(200);}catch(InterruptedException e){return;}}}},"engine-cancel");monitor.setDaemon(true);monitor.start();try{watch.stage("unity-engine","引擎正在定位功能数据并重建 Unity 资源，可能需要数分钟");loader.loadClass(m.getString("entry_class")).getMethod("apply",File.class,File.class,File.class,String.class,String.class).invoke(null,before,after,work,map,rules.toString());FilesEx.check(watch);}catch(java.lang.reflect.InvocationTargetException e){Throwable cause=e.getCause();if(cause instanceof Exception)throw (Exception)cause;throw new IOException("E_ENGINE_EXECUTION",cause);}finally{finished.set(true);monitor.interrupt();Thread.interrupted();}}
}
